<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;"
                                    >Masters</a></li>
                                <li class="breadcrumb-item active" aria-current="page" ><span>Good Return Notes</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>
            <span v-html="refreshButton(getReturnNotes,loading_spinner)"></span>
                    <!-- loading spinner starts -->
                 <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->

        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="returnNotes" :columns="columns" :options="table_option" >
                            <template #actions="props">
                                <div class="d-flex justify-content-center align-items-center"></div>

                                 <a
                  href="javascript:void(0);"
                  class="text-secondary position-relative me-2"
                  @click="
                    fillModal(props.row);
                    noteModalRef.open(null, props.row.id);
                  "
                >
                  <i class="bi bi-journal-bookmark-fill fs-5"></i>
                  <span
                    v-if="props.row.logs_count > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.logs_count }}
                  </span>
                </a>
                              
                                        <a href="javascript:;" class="edit me-2" 
                                             data-bs-toggle="modal" 
                                             data-bs-target="#view_store"
                                             id="back-modal"
                                            @click="fillModal(props.row)"
                                        >
   <i class="text-primary bi bi-eye fs-4" ></i>

                                        </a>

                                        <a href="javascript:;" class="edit me-2" 
                                             data-bs-toggle="modal" 
                                             data-bs-target="#edit-modal"
                                             id="back-modal"
                                            @click="OpenEditModal(props.row);"
                                              v-if="user_permissions.includes('can_edit_good_return_note')"
                                        >
   <i class="text-primary bi bi-pencil-square fs-4" ></i>

                                        </a>
                                        
                        
                            </template>
                               <template #status="props">
                    <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                      {{ props.row.status.name }}
                    </span>
                  </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
   </div>
 





     <!-- store preview modal starts -->
        <div class="modal fade mymodal" id="view_store" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-6" id="staticBackdropLabel"> {{ store.source_store }} - {{ store.returned_to }} </h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" @click="clearForm"></button>
      </div>
<div class="modal-body" >

 
    <form 
    v-if="note.status_id !== 10"
    @submit.prevent="receiverRemark(note)">

          <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <table class="table table-bordered mb-4">
                            <thead>
                                <tr>
                                    <th>Item</th>
                                    <th>Returned</th>
                                    <th>Shortage</th>
                                    <th>Received</th>
                                    <th>Condition</th>
                                    <th>Remark</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-for="(item, idx) in storeItems" :key="item.id || idx">
                                    <td>{{ item.item }}</td>
                                    <td>{{ item.returned_quantity }}</td>
                                    <td>{{ item.shortage_quantity }}</td>


<td>
    <div class="mb-1">
        <small class="text-muted">Received:</small>
        <span class="fw-bold text-primary ms-1">
            {{ item.received_quantity ?? 0 }}
        </span>
    </div>

    <input
        type="number"
        class="form-control"
        v-model="item.new_received_quantity"
        placeholder="Received qty"
        step="any"
        @input="item.new_received_quantity = enforceMax(item.new_received_quantity,item.shortage_quantity,)"
        required
        :disabled="Number(item.shortage_quantity) === 0"
    />
</td>


<td>
    <select
        v-model="item.condition"
        class="form-control form-select"
        :disabled="Number(item.shortage_quantity) === 0"
    >
        <option value="" disabled>Select Item Condition</option>
        <option value="new">new</option>
        <option value="used">used</option>
        <option value="damaged">damaged</option>
    </select>
</td>

<td>
    <input
        type="text"
        class="form-control"
        v-model="item.remarks"
        placeholder="Enter Remark"
        :disabled="Number(item.shortage_quantity) === 0"
    />
</td>
                                </tr>
                            </tbody>
                        </table>
                        </div>
                        </div>
                        </div>
                        </div>
        <textarea class="form-control" placeholder="Enter General Remarks"  v-model="remark" ></textarea>
        <div class="d-flex">
            <div class="ms-auto">
              <button type="submit" class="btn btn-primary mt-1" :disabled="sending">
                <span v-if="sending" v-html="loadingSpinner()">
                </span>
                <span v-else>
                  Submit
                </span>
            </button>
            </div>
        </div>
    </form>

          <div v-if="note.status_id === 10" class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="storeItems" :columns="itemsColumns" :options="table_option" >
                            <template #actions="props">
                                <div class="d-flex justify-content-center align-items-center"></div>                
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
        
    <div v-if="note.remark" class="mb-3">
        <label class="form-label fw-bold">Remark:</label>
        <div class="border rounded p-3 bg-light">
            {{ note.remark }}
        </div>
    </div >

      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>

      </div>

    </div>
  </div>

</div>
      <!-- store preview modal ends -->


      <!-- store preview modal starts -->
          <div class="modal fade mymodal" id="edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel"> Edit Return Note No. {{ note.id }} </h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" @click="clearForm"></button>
      </div>
      <form @submit.prevent="updateReturnNote(note.id)">
<div class="modal-body" >
      <div class="row mb-3">
            <div class="col-md-6">
                <label for="item">Source Store</label>
                <multiselect 
                    v-model="sourceStore"
                    :options= "stores"
                    placeholder="select store"
                    label="name"
                    :searchable = "true"        
                    multple="false"
                    :required="true"
                    :allow-empty="false"
                ></multiselect>
                </div>
           <div class="col-md-6">
            <label for="item">Destination Store</label>
                <multiselect 
                    v-model="destinationStore"
                    :options= "stores"
                    placeholder="select Store"
                    label="name"
                    :searchable = "true"        
                    multple="false"
                    :required="true"
                    :allow-empty="false"
                ></multiselect>
           </div>
           
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="updating">
            <span v-if="updating" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
      <!-- store preview modal ends -->


<NoteModal
      ref="noteModalRef"
      :source-id="id"
      source="GRT"
      module="GOOD RETURN NOTES"
      title="Grt"
      @logs-updated="(count) => (store.logs_count = count)"
    />


</template>

<script setup>
    import { onMounted, ref,inject,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Return Notes' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import NoteModal from "@/components/reusables/NoteModal.vue";
    const noteModalRef = ref(null);
     import { useRoute } from 'vue-router';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    // const whatsappAlert = inject("whatsappAlert");
    const route = useRoute();
    const sending = ref(false)
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner');
    const user = JSON.parse(localStorage.getItem("user"));
    const loading_spinner = ref(false);
    const columns = ref(['SNo','return_no', 'source_store','returned_to','issuer','receiver','status','date_returned','actions']);
    const itemsColumns = ref(['SNo', 'item','returned_quantity','received_quantity','remark']);
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const formatDate = inject('formatDate');
    const enforceMax = inject('enforceMax');
    const refreshButton = inject('refreshButton')
    const project = ref('')
    const name = ref('')
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    
    const remark = ref('')
    const receiverRemark = async(note)=>{
        sending.value = true
       const hasShortage = storeItems.value.some(
        (item) => Number(item.received_quantity) < Number(item.returned_quantity)
    )
    const status_id = hasShortage ? 35 : 10

    const payload = {
        destination_store : note.destination_store_id,
        status_id,
        receiver_id : user.id,
            source_store : store.value.source_store,
            remark : remark.value,
            items :storeItems.value.map((item)=>({
                id :item.id,
                item_id: item.item_id,
                returned_quantity : item.returned_quantity,
                received_quantity : item.new_received_quantity,
                remark : item.remarks ?? null,
                condition : item.condition ?? null,
            }))
        }

        console.log(payload)

        try{
        const response = await axiosInstance.put(`good-return-notes/${note.id}`,payload)
        showMessage("remark saved")
        getReturnNotes()
        document.getElementById('close').click()
        remark.value = ''
        const message = JSON.parse(localStorage.getItem('user')).name + ' Received items from ' + note.source_store;
        const receiver = '255698267662'
        const message_id = 'wamid.HBgMMjU1Njk4MjY3NjYyFQIAEhgWM0VCMDE4NkNGOENGMzEwRDNGQzJFRAA='
        whatsappAlert(message,message_id,receiver)
        }catch(error){
            showError(error.message)
            console.log(error)
        }finally{
            sending.value = false
        }

    }

    const table_option = ref({
        perPage: 100,
        perPageValues: [100,200, 500],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: [],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });
    
    const store = ref('')
    const note = ref('')
const fillModal = (data) => {
    console.log(data)
    store.value = data;
    note.value = data
    project.value = data.project || '';
    name.value = data.name || '';
    storeItems.value = data.items.map((item,index)=>({
        ...item,
        SNo : index + 1,
        item : item.item.name,
    }))
}


    const returnNotes = ref([])
    const getReturnNotes = async (showSpinner = true) => {
        if (showSpinner) loading_spinner.value = true;
       
        try {
        let url = '/good-return-notes';
        if (route.params.store_id !== 'all') {
            url += `?store_id=${route.params.store_id}`;
        }
        const response = await axiosInstance.get(url);
        returnNotes.value = response.data.map((note, index) => ({
            ...note,
            SNo: index + 1,
            return_no: note.id,
            source_store_id : note.source_store?.id,
            destination_store_id : note.destination_store?.id,
            source_store: note.source_store?.project.short_name + ' : ' + note.source_store?.name,
            returned_to: note?.destination_store?.project?.short_name + ' : ' + note?.destination_store?.name,
            issuer: note.issuer.name,
            receiver: note?.receiver?.name,
            date_returned: formatDate(note.created_at),
        }));
        } catch (error) {
        showError(error.message);
        console.log(error);
        } finally {
        if(showSpinner) loading_spinner.value = false;
        }
    }

    watch(
        () => route.params,
        () => {
        loading_spinner.value = true;
        getReturnNotes();
        },
        { deep: true }
    );


    const storeItems = ref([])


     const stores = ref([]);
    const getStores = async () => {
        try {
            const response = await axiosInstance.get('/get-stores');
            stores.value = response.data;
        } catch (error) {
            showError(error.message);
        }
    };

    const OpenEditModal = (data) => {
        note.value = data;
        sourceStore.value = stores.value.find(
        store => store.id === data.source_store_id
    );

    destinationStore.value = stores.value.find(
        store => store.id === data.destination_store_id
    );
    };

    const closeEditModal = () => {
        sourceStore.value = '';
        destinationStore.value = '';
    };

    const sourceStore = ref('');
    const updating = ref(false);
    const destinationStore = ref('');
    const updateReturnNote = async (id) => {
        updating.value = true;
        const payload = {
            source_store_id: sourceStore.value.id,
            destination_store_id: destinationStore.value.id,
        };
        try {
            const response = await axiosInstance.put(`/good-return-notes/${id}`, payload);
            getReturnNotes(false);
            document.getElementById('close_editing').click();
            showMessage('Return Note updated successfully!');
            closeEditModal();
        } catch (error) {
            showError(error.message);
        } finally {
            updating.value = false;
        }
    };

    onMounted(() => {
        getReturnNotes();
        getStores()
    });
</script>
